tool.schemaJson:
{
  "type": "object",
  "properties": {
    "screenName": {
      "type": "string",
      "description": "Name of the screen to create. Must be unique (UK constraint)."
    },
    "displayName": {
      "type": "string",
      "description": "Optional display name. If omitted, falls back to screenName."
    },
    "screenWidth": {
      "type": "integer",
      "description": "Canvas width in pixels (e.g. 1920)."
    },
    "screenHeight": {
      "type": "integer",
      "description": "Canvas height in pixels (e.g. 1080)."
    },
    "adaptorMode": {
      "type": "integer",
      "description": "Optional adaptation mode: 0=HEIGHT_FIRST, 10=FULL (default), 20=KEEP."
    },
    "backgroundConfig": {
      "type": "object",
      "description": "Optional screen background/theme config. May contain 'palette' (name to hex color map) and 'background' ({type,value}).",
      "additionalProperties": true
    },
    "widgets": {
      "type": "array",
      "description": "Widgets to place on the free-canvas screen. All 14 component types are allowed (including decorative/media). Each widget needs an absolute position (x,y) and size (w,h). Widgets MUST NOT exceed canvas bounds (x+w must be no more than screenWidth, y+h must be no more than screenHeight). Overlap is allowed (for decorative layering).",
      "items": {
        "type": "object",
        "properties": {
          "componentType": {
            "type": "string",
            "description": "One of the 14 registered component types. Call datav-list-component-types to see them all."
          },
          "datasetSid": {
            "type": "string",
            "description": "The nop-report dataset ID (sid) to bind this widget to. Required for chart/table/stat-tile/pivot-table/map (needsDataset=true). Omit/ignored for text/iframe/container and all decorative/media types (needsDataset=false). The dataset MUST be active (status=1) AND visible to the current user (created by the current user, or you are acting as admin); a non-existent/inactive dataset returns ERR_DATAV_CHATBI_GENERATE_DATASET_NOT_FOUND, an existing active dataset that is NOT visible to the current user returns ERR_DATAV_CHATBI_DATASET_NO_ACCESS. Stored directly as the logical datasetRefId (no DatasetRef row created)."
          },
          "fieldMapping": {
            "type": "object",
            "description": "Optional field mapping config stored in widgetConfig.fieldMapping. Each referenced field name MUST exist in the dataset's dsMeta field set (when datasetSid is provided). Example: {\"x\":\"region\",\"y\":\"amount\"}.",
            "additionalProperties": true
          },
          "x": {
            "type": "integer",
            "description": "X coordinate (left edge). Must be non-negative. x+w must be no more than screenWidth."
          },
          "y": {
            "type": "integer",
            "description": "Y coordinate (top edge). Must be non-negative. y+h must be no more than screenHeight."
          },
          "w": {
            "type": "integer",
            "description": "Width in pixels. Must be positive."
          },
          "h": {
            "type": "integer",
            "description": "Height in pixels. Must be positive."
          },
          "z": {
            "type": "integer",
            "description": "Optional z-index (stacking order). Defaults to 0."
          }
        },
        "required": ["componentType", "x", "y", "w", "h"]
      }
    }
  },
  "required": ["screenName", "screenWidth", "screenHeight", "widgets"]
}
